// Package tpt contains the embedded Two-Plus-Two lookup table.
//
// The table is split into multiple files to stay under GitHub's file size
// limit. The files are generated by internal/cmd/twoplustwogen, and when
// recombined have the same hash as the table generated by the reference C
// implementation.
//
// Only the twoplustwo package (and tests) import this package, so the table
// is only linked into binaries that import twoplustwo.
package tpt

//go:generate go run ../cmd/twoplustwogen

import (
	_ "embed"
	"encoding/binary"
	"fmt"
	"sync"
)

// Embedded lookup table.
var (
	//go:embed twoplustwo00.dat
	twoplustwo00Dat []byte
	//go:embed twoplustwo01.dat
	twoplustwo01Dat []byte
	//go:embed twoplustwo02.dat
	twoplustwo02Dat []byte
	//go:embed twoplustwo03.dat
	twoplustwo03Dat []byte
	//go:embed twoplustwo04.dat
	twoplustwo04Dat []byte
	//go:embed twoplustwo05.dat
	twoplustwo05Dat []byte
	//go:embed twoplustwo06.dat
	twoplustwo06Dat []byte
	//go:embed twoplustwo07.dat
	twoplustwo07Dat []byte
	//go:embed twoplustwo08.dat
	twoplustwo08Dat []byte
	//go:embed twoplustwo09.dat
	twoplustwo09Dat []byte
	//go:embed twoplustwo10.dat
	twoplustwo10Dat []byte
	//go:embed twoplustwo11.dat
	twoplustwo11Dat []byte
	//go:embed twoplustwo12.dat
	twoplustwo12Dat []byte
)

// Table returns the ~124 MiB lookup table, decoding it on first use.
var Table = sync.OnceValue(func() []uint32 {
	const total, chunk, last = 32487834, 2621440, 1030554
	chunks := [...][]byte{
		twoplustwo00Dat,
		twoplustwo01Dat,
		twoplustwo02Dat,
		twoplustwo03Dat,
		twoplustwo04Dat,
		twoplustwo05Dat,
		twoplustwo06Dat,
		twoplustwo07Dat,
		twoplustwo08Dat,
		twoplustwo09Dat,
		twoplustwo10Dat,
		twoplustwo11Dat,
		twoplustwo12Dat,
	}
	table, pos := make([]uint32, total), 0
	for i, buf := range chunks {
		n, exp := len(buf), chunk
		if i == len(chunks)-1 {
			exp = last
		}
		if n%4 != 0 || n/4 != exp {
			panic(fmt.Sprintf("twoplustwo%02d.dat is bad: expected %d uint32, has: %d", i, exp, n/4))
		}
		for ; len(buf) != 0; buf = buf[4:] {
			table[pos] = binary.LittleEndian.Uint32(buf)
			pos++
		}
	}
	return table
})
